//! The TOML text of one category catalog, in the toggle catalog schema.

use std::fmt::Write as _;

use super::{App, Category};

const HEADER: &str = "\
# Discover apps of one category, from the Arch wiki's application lists.
# Generated by `cargo xtask wiki-sync`. Edits are lost on the next sync.
#
# `id` comes from the first package and never changes (selftests and
# translations refer to it). `check` is that package, `also` the others
# installed with it, `url` the app's website.
";

/// The entry id of an app: its first package as lowercase words joined by
/// dashes, `+` spelled out (`nicotine+` is `nicotine-plus`). `None` for an
/// app that misses a package, a title or a description.
pub fn entry_id(app: &App) -> Option<String> {
    let package = app.packages.first()?;

    if app.title.trim().is_empty() || app.description.trim().is_empty() {
        return None;
    }

    let mut id = String::with_capacity(package.len());

    for letter in package.chars() {
        match letter {
            'a'..='z' | '0'..='9' => id.push(letter),
            'A'..='Z' => id.push(letter.to_ascii_lowercase()),
            '+' => id.push_str("-plus-"),
            _ => id.push('-'),
        }
    }

    let words: Vec<&str> = id.split('-').filter(|word| !word.is_empty()).collect();

    (!words.is_empty()).then(|| words.join("-"))
}

/// The catalog file of one category, each app with its [`entry_id`].
pub fn render(category: Category, apps: &[(String, App)]) -> String {
    let mut text = String::from(HEADER);

    // Writing to a String cannot fail.
    write!(
        text,
        "\n[[section]]\nid = {}\ntitle = {}\nicon = {}\n",
        quoted(category.id),
        quoted(category.title),
        quoted(category.icon)
    )
    .ok();

    for (id, app) in apps {
        // An app with an id has a package.
        let Some((package, also)) = app.packages.split_first() else {
            continue;
        };

        write!(
            text,
            "\n[[section.entry]]\nid = {}\ntitle = {}\ndescription = {}\ncheck = {{ package = {} }}\n",
            quoted(id),
            quoted(app.title.trim()),
            quoted(app.description.trim()),
            quoted(package)
        )
        .ok();

        if !also.is_empty() {
            let list: Vec<String> = also
                .iter()
                .map(|name| format!("{{ package = {} }}", quoted(name)))
                .collect();

            writeln!(text, "also = [{}]", list.join(", ")).ok();
        }

        if let Some(url) = &app.url {
            writeln!(text, "url = {}", quoted(url)).ok();
        }
    }

    text
}

pub fn quoted(text: &str) -> String {
    let mut literal = String::with_capacity(text.len() + 2);

    literal.push('"');

    for letter in text.chars() {
        match letter {
            '"' => literal.push_str("\\\""),
            '\\' => literal.push_str("\\\\"),
            '\n' => literal.push_str("\\n"),
            '\t' => literal.push_str("\\t"),
            control if control.is_control() => {
                write!(literal, "\\u{:04X}", u32::from(control)).ok();
            }
            other => literal.push(other),
        }
    }

    literal.push('"');

    literal
}
